<?php $id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT r.*,b.full_name borrower,b.status borrower_status,c.name category,(SELECT name FROM equipment WHERE id=r.equipment_id) equipment_name,u.full_name creator FROM loan_requests r JOIN borrowers b ON b.id=r.borrower_id JOIN equipment_categories c ON c.id=r.category_id LEFT JOIN users u ON u.id=r.created_by WHERE r.id=?');$s->execute([$id]);$r=$s->fetch();if(!$r)redirect('?page=requests');$s=$pdo->prepare('SELECT COUNT(*) FROM equipment_items i JOIN equipment e ON e.id=i.equipment_id WHERE e.category_id=? AND (?=0 OR e.id=?) AND i.status=\'Available\' AND i.condition_label IN (\'Good\',\'Fair\')');$s->execute([$r['category_id'],(int)($r['equipment_id']??0),(int)($r['equipment_id']??0)]);$available=(int)$s->fetchColumn();$error='';verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';if($action!=='cancel'&&$r['status']!=='Pending')$error='Only pending requests can be reviewed.';elseif($action==='approve'){if($r['borrower_status']!=='Active')$error='Inactive borrowers cannot have requests approved.';elseif($available<(int)$r['quantity'])$error='Insufficient available equipment for the requested quantity.';else{$s=$pdo->prepare("UPDATE loan_requests SET status='Approved',reviewed_by=?,reviewed_at=NOW() WHERE id=? AND status='Pending'");$s->execute([user()['id'],$id]);log_activity($pdo,'Approved loan request','request',$id);flash('Request approved. Issue the items when the borrower collects them.');redirect('?page=request-view&id='.$id);}}elseif($action==='reject'){$s=$pdo->prepare("UPDATE loan_requests SET status='Rejected',reviewed_by=?,reviewed_at=NOW() WHERE id=? AND status='Pending'");$s->execute([user()['id'],$id]);log_activity($pdo,'Rejected loan request','request',$id);flash('Request rejected.');redirect('?page=request-view&id='.$id);}elseif($action==='cancel'){if($r['status']==='Pending'||$r['status']==='Approved'){$s=$pdo->prepare("UPDATE loan_requests SET status='Cancelled',reviewed_by=?,reviewed_at=NOW() WHERE id=? AND status IN ('Pending','Approved')");$s->execute([user()['id'],$id]);log_activity($pdo,'Cancelled loan request','request',$id);flash('Request cancelled.');redirect('?page=request-view&id='.$id);}else{$error='Only pending or approved requests can be cancelled.';}}}$s=$pdo->prepare('SELECT COUNT(*) FROM equipment_items i JOIN equipment e ON e.id=i.equipment_id WHERE e.category_id=? AND (?=0 OR e.id=?) AND i.status=\'Available\' AND i.condition_label IN (\'Good\',\'Fair\')');$s->execute([$r['category_id'],(int)($r['equipment_id']??0),(int)($r['equipment_id']??0)]);$available=(int)$s->fetchColumn();layout_start('Request details','requests'); ?><div class="page-heading"><div><a class="back-link" href="?page=requests">← Loan requests</a><h1>Request #<?=str_pad((string)$id,4,'0',STR_PAD_LEFT)?></h1><p class="muted">Submitted <?=date('j M Y',strtotime($r['created_at']))?></p></div><span class="badge <?=strtolower($r['status'])?> large-badge"><?=h($r['status'])?></span></div><?php if($error): ?><div class="alert error"><?=h($error)?></div><?php endif; ?><div class="detail-grid"><section class="panel"><h2>Request details</h2><dl class="detail-list"><dt>Borrower</dt><dd><a class="text-link" href="?page=borrower-view&id=<?=$r['borrower_id']?>"><?=h($r['borrower'])?></a></dd><dt>Equipment</dt><dd><?=h($r['equipment_name']?:$r['category'])?><?=$r['equipment_name']?' ('.h($r['category']).')':''?> · <?=$r['quantity']?> item(s)</dd><dt>Requested period</dt><dd><?=date('j M Y',strtotime($r['start_date']))?> to <?=date('j M Y',strtotime($r['due_date']))?></dd><dt>Available now</dt><dd><?=$available?> matching item(s) in stock</dd><dt>Notes</dt><dd><?=nl2br(h($r['notes']?:'None'))?></dd><dt>Submitted by</dt><dd><?=h($r['creator']??'Borrower (online request)')?></dd></dl></section><section class="panel"><h2>Review request</h2><p class="muted">Approve only when there is enough available equipment.</p><?php if($r['status']==='Pending'): ?><div class="button-row"><form method="post" onsubmit="return confirm('Approve this request?')"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="approve"><button class="button primary">Approve request</button></form><form method="post" onsubmit="return confirm('Reject this request?')"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="reject"><button class="button danger">Reject</button></form></div><?php elseif($r['status']==='Approved'): ?><a class="button primary" href="?page=issue&request=<?=$id?>">Issue equipment</a><?php if($r['status']==='Approved'): ?><form method="post" class="inline-form" onsubmit="return confirm('Cancel this approved request?')"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="cancel"><button class="button ghost">Cancel request</button></form><?php endif; ?><?php else: ?><p class="muted">This request has been <?=h(strtolower($r['status']))?>.</p><?php endif; ?></section></div><?php layout_end();
